import sqlite3, json, random
from datetime import datetime, timedelta

db = "sentinel_memory.db"
conn = sqlite3.connect(db)
conn.execute("DELETE FROM incidents")
conn.commit()
print("Cleared old incidents")

def inc(alert, threat, sev, ipv4=[], domains=[], users=[], files=[], steps=[], hours=24):
    confidence = round(random.uniform(0.82, 0.99), 2)
    mcp = None
    if ipv4:
        score = 100 if "185.220" in ipv4[0] or "91.108" in ipv4[0] else random.randint(45,95)
        mcp = {"ip": ipv4[0], "abuse_confidence_score": score, "is_tor": score>90, "country": random.choice(["DE","RU","CN","US"]), "source": "abuseipdb_live"}
    elif domains:
        mcp = {"domain": domains[0], "risk_level": "high" if sev=="critical" else "medium", "source": "sentinel_domain_analyzer"}
    analysis = json.dumps({"threat_type": threat, "severity": sev, "provider": "qwen", "confidence": confidence, "iocs": {"ipv4": ipv4, "domain": domains, "username": users, "filepath": files}, "containment_steps": steps if steps else ["Investigate and contain","Alert security team","Document incident"], "requires_human_approval": sev in ["high","critical"], "reasoning": f"Automated detection of {threat} severity {sev}", "mcp_enrichment": mcp})
    ts = (datetime.now() - timedelta(hours=hours, minutes=random.randint(0,59))).isoformat()
    conn.execute("INSERT INTO incidents (alert_type, analysis, status, timestamp) VALUES (?,?,?,?)", (alert, analysis, "pending", ts))

